import{_ as d,o as s,c as n,a4 as i}from"./chunks/framework.B-wJupoK.js";const c=JSON.parse('{"title":"07-数字类型（2）","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/07-数字类型（2）/07-数字类型（2）.md","filePath":"仓颉入门到实战/07-数字类型（2）/07-数字类型（2）.md","lastUpdated":1734307884000,"__rawMarkdown":"# 07-数字类型（2）\\n\\n## 整数类型字面量\\n\\n**整数字面量就是一眼能看出来是整数的字面的代码**\\n\\n如：\\n\\n```\\n100 整数\\n200 整数\\nxdfds  不是整数\\n```\\n\\n其中，整数类型字面量有 4 种进制表示形式：二进制（使用 `0b` 或 `0B` 前缀）、八进制（使用 `0o` 或 `0O` 前缀）、十进制（没有前缀）、十六进制（使用 `0x` 或 `0X` 前缀）。例如，对于十进制数 `24`，表示成二进制是 `0b00011000`（或 `0B00011000`），表示成八进制是 `0o30`（或 `0O30`），表示成十六进制是 `0x18`（或 `0X18`）。默认的数字都是十进制。如 `100` ,一般可以理解为 就是 十进制中的 `100`\\n\\n在各进制表示中，可以使用下划线 `_` 充当分隔符的作用，方便识别数值的位数，如 `0b0001_1000`。\\n\\n对于整数类型字面量，如果它的值超出了上下文要求的整数类型的表示范围，编译器将会报错。\\n\\n```typescript\\nlet x: Int8 = 128; // Error, 128 out of the range of Int8\\nlet y: UInt8 = 256; // Error, 256 out of the range of UInt8\\nlet z: Int32 = 0x8000_0000; // Error, 0x8000_0000 out of the range of Int32\\n```\\n\\n在使用整数类型字面量时，可以通过加入**后缀**来明确整数字面量的类型，后缀与类型的对应为：\\n\\n| 后缀 | 类型  | 后缀 | 类型   |\\n| :--- | :---- | :--- | :----- |\\n| i8   | Int8  | u8   | UInt8  |\\n| i16  | Int16 | u16  | UInt16 |\\n| i32  | Int32 | u32  | UInt32 |\\n| i64  | Int64 | u64  | UInt64 |\\n\\n加入了后缀的整数字面量可以像下面的方式来使用：\\n\\n```typescript\\nvar x = 100i8  // x is 100 with type Int8\\nvar y = 0x10u64 // y is 16 with type UInt64\\nvar z = 0o432i32  // z is 282 with type Int32\\n```\\n\\n## 字符字节字面量\\n\\n仓颉编程语言支持字符字节字面量，以方便使用 ASCII 码表示 `UInt8` 类型的值。字符字节字面量由字符 b、一对标识首尾的单引号、以及一个 `ASCII` 字符组成，例如：\\n\\n```typescript\\nvar a = b\'x\' // a is 120 with type UInt8\\nvar b = b\'\\\\n\' // b is 10 with type UInt8\\nvar c = b\'\\\\u{78}\' // c is 120 with type UInt8\\n```\\n\\n`b\'x\'` 表示类型为 UInt8 大小是 120 的字面值。另外还可以通过 `b\'\\\\u{78}\'` 这种转义形式表示类型为 `UInt8`，16 进制大小为 0x78 或 10 进制大小为 120 的字面值。需要注意的是，`\\\\u` 内部最多有两位 16 进制数，并且值必须小于 256（十进制）。\\n\\n### ASCII 表\\n\\n| 十进制 | 十六进制 | 字符 |\\n| ------ | -------- | ---- |\\n| 48     | 30       | 0    |\\n| 49     | 31       | 1    |\\n| 50     | 32       | 2    |\\n| 51     | 33       | 3    |\\n| 52     | 34       | 4    |\\n| 53     | 35       | 5    |\\n| 54     | 36       | 6    |\\n| 55     | 37       | 7    |\\n| 56     | 38       | 8    |\\n| 57     | 39       | 9    |\\n| 65     | 41       | A    |\\n| 66     | 42       | B    |\\n| 67     | 43       | C    |\\n| 68     | 44       | D    |\\n| 69     | 45       | E    |\\n| 70     | 46       | F    |\\n| 71     | 47       | G    |\\n| 72     | 48       | H    |\\n| 73     | 49       | I    |\\n| 74     | 4A       | J    |\\n| 75     | 4B       | K    |\\n| 76     | 4C       | L    |\\n| 77     | 4D       | M    |\\n| 78     | 4E       | N    |\\n| 79     | 4F       | O    |\\n| 80     | 50       | P    |\\n| 81     | 51       | Q    |\\n| 82     | 52       | R    |\\n| 83     | 53       | S    |\\n| 84     | 54       | T    |\\n| 85     | 55       | U    |\\n| 86     | 56       | V    |\\n| 87     | 57       | W    |\\n| 88     | 58       | X    |\\n| 89     | 59       | Y    |\\n| 90     | 5A       | Z    |\\n| 97     | 61       | a    |\\n| 98     | 62       | b    |\\n| 99     | 63       | c    |\\n| 100    | 64       | d    |\\n| 101    | 65       | e    |\\n| 102    | 66       | f    |\\n| 103    | 67       | g    |\\n| 104    | 68       | h    |\\n| 105    | 69       | i    |\\n| 106    | 6A       | j    |\\n| 107    | 6B       | k    |\\n| 108    | 6C       | l    |\\n| 109    | 6D       | m    |\\n| 110    | 6E       | n    |\\n| 111    | 6F       | o    |\\n| 112    | 70       | p    |\\n| 113    | 71       | q    |\\n| 114    | 72       | r    |\\n| 115    | 73       | s    |\\n| 116    | 74       | t    |\\n| 117    | 75       | u    |\\n| 118    | 76       | v    |\\n| 119    | 77       | w    |\\n| 120    | 78       | x    |\\n| 121    | 79       | y    |\\n| 122    | 7A       | z    |\\n| 33     | 21       | !    |\\n| 34     | 22       | \\"    |\\n| 35     | 23       | #    |\\n| 36     | 24       | $    |\\n| 37     | 25       | %    |\\n| 38     | 26       | &    |\\n| 39     | 27       | \'    |\\n| 40     | 28       | (    |\\n| 41     | 29       | )    |\\n| 42     | 2A       | \\\\*   |\\n| 43     | 2B       | +    |\\n| 44     | 2C       | ,    |\\n| 45     | 2D       | -    |\\n| 46     | 2E       | .    |\\n| 47     | 2F       | /    |\\n| 58     | 3A       | :    |\\n| 59     | 3B       | ;    |\\n| 60     | 3C       | <    |\\n| 61     | 3D       | =    |\\n| 62     | 3E       | >    |\\n| 63     | 3F       | ?    |\\n| 64     | 40       | @    |\\n| 91     | 5B       | [    |\\n| 92     | 5C       | \\\\|   |\\n| 93     | 5D       | ]    |\\n| 94     | 5E       | ^    |\\n| 95     | 5F       | \\\\_   |\\n| 96     | 60       | `    |\\n| 123    | 7B       | {    |\\n| 124    | 7C       |      |\\n| 125    | 7D       | }    |\\n| 126    | 7E       | ~    |\\n"}'),a={name:"仓颉入门到实战/07-数字类型（2）/07-数字类型（2）.md"};function r(e,t,l,p,h,k){return s(),n("div",null,[...t[0]||(t[0]=[i("",19)])])}const y=d(a,[["render",r]]);export{c as __pageData,y as default};
